/* ===== StayQuest Design System ===== */
:root {
  --navy: #003B95;
  --navy-dark: #002a6e;
  --navy-light: #004cb8;
  --blue: #006CE4;
  --blue-light: #e8f2fd;
  --gold: #FFB700;
  --gold-dark: #e6a500;
  --gold-light: #fff7e0;
  --white: #FFFFFF;
  --gray-50: #f8f9fa;
  --gray-100: #f0f2f5;
  --gray-200: #e4e7ec;
  --gray-300: #ced2d9;
  --gray-400: #9ba3af;
  --gray-500: #6b7280;
  --gray-600: #4b5563;
  --gray-700: #374151;
  --gray-800: #1f2937;
  --gray-900: #111827;
  --green: #059669;
  --red: #dc2626;
  --red-light: #fef2f2;
  --radius-sm: 6px;
  --radius: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.06);
  --shadow: 0 2px 8px rgba(0,0,0,0.08);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.1);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.12);
  --font: 'Inter', 'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --max-width: 1200px;
  --header-height: 68px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }

body {
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.6;
  color: var(--gray-800);
  background: var(--white);
  min-height: 100vh;
}

img { max-width: 100%; display: block; }
a { color: var(--blue); text-decoration: none; }
a:hover { text-decoration: underline; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul { list-style: none; }

/* ===== Typography ===== */
h1, h2, h3, h4 { color: var(--gray-900); line-height: 1.25; }
h1 { font-size: 2.5rem; font-weight: 800; }
h2 { font-size: 1.75rem; font-weight: 700; }
h3 { font-size: 1.25rem; font-weight: 600; }

/* ===== Layout ===== */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.section { padding: 72px 0; }
.section--alt { background: var(--gray-50); }
.section-header { text-align: center; margin-bottom: 40px; }
.section-header h2 { margin-bottom: 8px; }
.section-header p { color: var(--gray-500); font-size: 1.075rem; }

/* ===== Header / Navigation ===== */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: var(--navy);
  height: var(--header-height);
  box-shadow: 0 2px 12px rgba(0,0,0,0.15);
}
.site-header .container {
  display: flex; align-items: center; justify-content: space-between;
  height: 100%;
}
.logo {
  display: flex; align-items: center; gap: 10px;
  color: var(--white); font-size: 1.35rem; font-weight: 800;
  text-decoration: none; letter-spacing: -0.02em;
}
.logo:hover { text-decoration: none; opacity: 0.9; }
.logo-icon {
  width: 34px; height: 34px;
  background: var(--gold);
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  color: var(--navy); font-size: 1.1rem; font-weight: 900;
}
.nav-links { display: flex; align-items: center; gap: 6px; }
.nav-links a {
  color: rgba(255,255,255,0.85);
  padding: 8px 16px;
  border-radius: 24px;
  font-size: 0.9rem; font-weight: 500;
  text-decoration: none;
  transition: all 0.15s ease;
  white-space: nowrap;
}
.nav-links a:hover,
.nav-links a.active {
  color: var(--white);
  background: rgba(255,255,255,0.12);
  text-decoration: none;
}
.nav-links a.active { background: rgba(255,255,255,0.2); font-weight: 600; }
.mobile-menu-btn { display: none; color: var(--white); font-size: 1.5rem; padding: 8px; }

/* ===== Buttons ===== */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 12px 28px;
  border-radius: 28px;
  font-size: 0.95rem; font-weight: 600;
  text-decoration: none;
  transition: all 0.15s ease;
  border: 2px solid transparent;
  white-space: nowrap;
}
.btn:hover { text-decoration: none; transform: translateY(-1px); }
.btn-primary { background: var(--blue); color: var(--white); border-color: var(--blue); }
.btn-primary:hover { background: #0059c7; border-color: #0059c7; }
.btn-gold { background: var(--gold); color: var(--gray-900); border-color: var(--gold); }
.btn-gold:hover { background: var(--gold-dark); border-color: var(--gold-dark); }
.btn-outline { background: transparent; color: var(--navy); border-color: var(--navy); }
.btn-outline:hover { background: var(--navy); color: var(--white); }
.btn-white { background: var(--white); color: var(--navy); }
.btn-white:hover { background: var(--gray-100); }
.btn-sm { padding: 8px 18px; font-size: 0.85rem; }

/* ===== Hero Section ===== */
.hero {
  background: linear-gradient(135deg, var(--navy) 0%, #002766 50%, var(--navy-dark) 100%);
  color: var(--white);
  padding: 80px 0 64px;
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at 30% 50%, rgba(0,108,228,0.25) 0%, transparent 60%),
              radial-gradient(ellipse at 70% 20%, rgba(255,183,0,0.1) 0%, transparent 50%);
  pointer-events: none;
}
.hero .container { position: relative; z-index: 1; }
.hero-content { text-align: center; max-width: 720px; margin: 0 auto 36px; }
.hero h1 { font-size: 2.75rem; color: var(--white); margin-bottom: 8px; }
.hero p { font-size: 1.15rem; color: rgba(255,255,255,0.8); }

.search-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 6px;
  box-shadow: var(--shadow-lg);
  max-width: 920px;
  margin: 0 auto;
  display: flex; align-items: center; gap: 4px;
  flex-wrap: wrap;
  position: relative;
}
.search-field {
  flex: 1; min-width: 140px;
  position: relative;
  padding: 10px 14px;
  border-radius: var(--radius);
  transition: background 0.15s;
}
.search-field:hover { background: var(--gray-50); }
.search-field:not(:last-child)::after {
  content: ''; position: absolute; right: 0; top: 20%; height: 60%;
  width: 1px; background: var(--gray-200);
}
.search-label {
  display: block; font-size: 0.75rem; font-weight: 600;
  color: var(--gray-500); text-transform: uppercase; letter-spacing: 0.04em;
  margin-bottom: 2px;
}
.search-input {
  width: 100%; border: none; outline: none;
  font-size: 0.925rem; color: var(--gray-800);
  background: transparent; font-family: inherit;
}
.search-input::placeholder { color: var(--gray-400); }
.search-btn {
  padding: 14px 32px;
  border-radius: 28px;
  font-size: 1rem; font-weight: 700;
  margin: 4px;
  flex-shrink: 0;
}
.search-extra {
  max-width: 920px; margin: 12px auto 0;
  display: flex; align-items: center; gap: 8px;
}
.search-extra label {
  display: flex; align-items: center; gap: 8px;
  color: rgba(255,255,255,0.9); font-size: 0.9rem; cursor: pointer;
}
.search-extra input[type="checkbox"] {
  width: 18px; height: 18px; accent-color: var(--gold); cursor: pointer;
}

/* Package radio group */
.package-radios {
  display: flex; flex-wrap: wrap; gap: 6px;
  max-width: 920px; margin: 0 auto 16px;
}
.package-radio-label {
  display: flex; align-items: center; gap: 8px;
  padding: 10px 18px;
  border-radius: 24px;
  background: rgba(255,255,255,0.1);
  color: rgba(255,255,255,0.9);
  font-size: 0.875rem; font-weight: 500;
  cursor: pointer; transition: all 0.15s;
  border: 2px solid transparent;
}
.package-radio-label:hover { background: rgba(255,255,255,0.18); }
.package-radio-label.active {
  background: var(--white);
  color: var(--navy);
  border-color: var(--white);
  font-weight: 600;
}
.package-radio-label input { display: none; }

/* Car rental extra options */
.search-checkboxes {
  max-width: 920px; margin: 12px auto 0;
  display: flex; flex-wrap: wrap; gap: 20px;
}

/* ===== Trust Badges ===== */
.trust-badges { padding: 48px 0; border-bottom: 1px solid var(--gray-200); }
.trust-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px;
}
.trust-item {
  display: flex; align-items: flex-start; gap: 14px;
}
.trust-icon {
  width: 44px; height: 44px; border-radius: var(--radius);
  background: var(--blue-light);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0; font-size: 1.3rem;
}
.trust-item h4 { font-size: 0.95rem; margin-bottom: 2px; font-weight: 600; }
.trust-item p { font-size: 0.85rem; color: var(--gray-500); }

/* ===== Offers ===== */
.offers-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.offer-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 36px; position: relative; overflow: hidden;
  box-shadow: var(--shadow);
  border: 1px solid var(--gray-200);
}
.offer-card--deal { background: linear-gradient(135deg, #fef9e7, #fff3cd); border-color: #f0d77b; }
.offer-card--credit { background: linear-gradient(135deg, #eff6ff, #dbeafe); border-color: #bdd5f5; }
.offer-card h3 { font-size: 1.35rem; margin-bottom: 8px; }
.offer-card p { color: var(--gray-600); margin-bottom: 20px; max-width: 400px; }

/* ===== Property Types ===== */
.property-types-list {
  display: flex; flex-wrap: wrap; gap: 10px;
  justify-content: center;
}
.property-type-tag {
  padding: 10px 20px;
  border-radius: 24px;
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  color: var(--gray-700);
  font-size: 0.875rem; font-weight: 500;
  transition: all 0.15s;
  cursor: pointer;
}
.property-type-tag:hover { border-color: var(--blue); color: var(--blue); background: var(--blue-light); }

/* ===== Trip Planner ===== */
.trip-planner-tabs {
  display: flex; flex-wrap: nowrap; gap: 0;
  overflow-x: auto;
  border-bottom: 2px solid var(--gray-200);
  margin-bottom: 32px;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.trip-planner-tabs::-webkit-scrollbar { display: none; }
.trip-planner-tab {
  padding: 12px 20px;
  font-size: 0.9rem; font-weight: 500;
  color: var(--gray-500);
  white-space: nowrap;
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
  transition: all 0.15s;
  cursor: pointer;
  background: none;
  font-family: inherit;
}
.trip-planner-tab:hover { color: var(--gray-700); }
.trip-planner-tab.active {
  color: var(--navy); font-weight: 600;
  border-bottom-color: var(--blue);
}
.trip-destinations {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px;
}
.trip-destination-card {
  display: flex; align-items: center; gap: 14px;
  padding: 16px; border-radius: var(--radius);
  border: 1px solid var(--gray-200);
  transition: all 0.15s; cursor: pointer;
}
.trip-destination-card:hover { box-shadow: var(--shadow); border-color: var(--gray-300); }
.trip-dest-img {
  width: 64px; height: 64px; border-radius: var(--radius-sm);
  background: linear-gradient(135deg, var(--blue-light), #d0e2ff);
  flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem;
}
.trip-dest-info h4 { font-size: 0.95rem; margin-bottom: 2px; }
.trip-dest-info span { font-size: 0.8rem; color: var(--gray-500); }

/* ===== Unique Properties Carousel ===== */
.carousel-wrapper { position: relative; }
.carousel-container { overflow-x: auto; scroll-snap-type: x mandatory; -webkit-overflow-scrolling: touch; scrollbar-width: none; }
.carousel-container::-webkit-scrollbar { display: none; }
.carousel-track { display: flex; gap: 20px; }
.carousel-btn {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 44px; height: 44px; border-radius: 50%;
  background: var(--white); box-shadow: var(--shadow-md);
  display: flex; align-items: center; justify-content: center;
  z-index: 10; font-size: 1.2rem; color: var(--gray-700);
  transition: all 0.15s;
}
.carousel-btn:hover { box-shadow: var(--shadow-lg); background: var(--gray-50); }
.carousel-btn--prev { left: -16px; }
.carousel-btn--next { right: -16px; }

/* ===== Property Cards ===== */
.property-card {
  flex: 0 0 calc(33.333% - 14px); min-width: 280px;
  border-radius: var(--radius-lg); overflow: hidden;
  background: var(--white); box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-200);
  transition: all 0.2s; cursor: pointer;
  scroll-snap-align: start;
}
.property-card:hover { box-shadow: var(--shadow); transform: translateY(-2px); }
.property-img {
  height: 200px; position: relative;
  background: linear-gradient(135deg, #dbeafe, #bfdbfe);
  display: flex; align-items: center; justify-content: center;
}
.property-img .placeholder-icon { font-size: 3rem; opacity: 0.4; }
.property-img .rating-badge {
  position: absolute; top: 12px; right: 12px;
  background: var(--navy); color: var(--white);
  padding: 4px 10px; border-radius: 12px;
  font-size: 0.8rem; font-weight: 700;
}
.property-body { padding: 16px; }
.property-body h3 { font-size: 0.95rem; margin-bottom: 4px; line-height: 1.3; font-weight: 600; }
.property-body .location { color: var(--gray-500); font-size: 0.85rem; margin-bottom: 8px; }
.property-body .meta { display: flex; align-items: center; gap: 12px; font-size: 0.8rem; color: var(--gray-500); margin-bottom: 10px; }
.property-body .meta .rating { font-weight: 700; color: var(--navy); }
.property-body .meta .reviews { color: var(--gray-400); }
.property-footer { display: flex; align-items: baseline; justify-content: space-between; padding-top: 10px; border-top: 1px solid var(--gray-100); }
.property-footer .price { font-size: 1.15rem; font-weight: 700; color: var(--gray-900); }
.property-footer .price-period { font-size: 0.8rem; color: var(--gray-500); }
.property-footer .old-price { text-decoration: line-through; color: var(--gray-400); font-size: 0.85rem; margin-right: 6px; }
.property-footer .sale-badge { background: var(--red-light); color: var(--red); padding: 3px 8px; border-radius: 4px; font-size: 0.75rem; font-weight: 600; }

/* ===== Trending / Explore Destinations ===== */
.trending-tags { display: flex; flex-wrap: wrap; gap: 12px; justify-content: center; }
.trending-tag {
  padding: 10px 22px;
  border-radius: 24px;
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  color: var(--gray-700);
  font-size: 0.9rem; font-weight: 500;
  transition: all 0.15s; cursor: pointer;
}
.trending-tag:hover { border-color: var(--blue); color: var(--blue); background: var(--blue-light); }

.destinations-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px; }
.dest-card {
  position: relative; border-radius: var(--radius-lg); overflow: hidden;
  aspect-ratio: 4/5; cursor: pointer;
  background: linear-gradient(135deg, #e0e7ff, #c7d2fe);
  display: flex; align-items: flex-end;
  transition: transform 0.2s;
}
.dest-card:hover { transform: translateY(-2px); }
.dest-card-overlay {
  padding: 20px; width: 100%;
  background: linear-gradient(transparent, rgba(0,0,0,0.7));
  color: var(--white);
}
.dest-card-overlay h3 { color: var(--white); font-size: 1rem; margin-bottom: 2px; }
.dest-card-overlay span { font-size: 0.8rem; opacity: 0.85; }

/* ===== Deal Cards (weekend deals variant) ===== */
.deals-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }

/* ===== Homes Guests Love ===== */
.homes-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
.homes-cta { text-align: center; margin-top: 32px; }

/* ===== Loyalty CTA ===== */
.loyalty-cta {
  background: linear-gradient(135deg, var(--navy) 0%, #002766 100%);
  color: var(--white); padding: 72px 0;
}
.loyalty-content { text-align: center; max-width: 600px; margin: 0 auto; }
.loyalty-content h2 { color: var(--white); font-size: 2rem; margin-bottom: 8px; }
.loyalty-content .subhead { color: var(--gold); font-weight: 600; margin-bottom: 12px; font-size: 1.05rem; }
.loyalty-content p { color: rgba(255,255,255,0.8); margin-bottom: 24px; }
.loyalty-buttons { display: flex; gap: 12px; justify-content: center; }

/* ===== Popular Links Tabs ===== */
.popular-tabs {
  display: flex; flex-wrap: wrap; gap: 8px;
  margin-bottom: 28px; justify-content: center;
}
.popular-tab {
  padding: 10px 22px;
  border-radius: 24px;
  font-size: 0.9rem; font-weight: 500;
  color: var(--gray-600);
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  transition: all 0.15s; cursor: pointer;
  font-family: inherit;
}
.popular-tab:hover { border-color: var(--blue); color: var(--blue); }
.popular-tab.active { background: var(--navy); color: var(--white); border-color: var(--navy); }
.popular-links-list {
  display: flex; flex-wrap: wrap; gap: 12px;
  justify-content: center;
}
.popular-link-item {
  padding: 8px 16px;
  color: var(--gray-600); font-size: 0.9rem;
  transition: color 0.15s; cursor: pointer;
  text-decoration: none;
}
.popular-link-item:hover { color: var(--blue); text-decoration: underline; }

/* ===== Benefits Section ===== */
.benefits-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
.benefit-card {
  text-align: center; padding: 36px 24px;
  border-radius: var(--radius-lg);
  background: var(--white);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-200);
}
.benefit-icon {
  width: 56px; height: 56px; border-radius: 50%;
  background: var(--blue-light); margin: 0 auto 16px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem;
}
.benefit-card h3 { margin-bottom: 8px; }
.benefit-card p { color: var(--gray-500); font-size: 0.925rem; }

/* ===== Companies Grid (Car Rental) ===== */
.companies-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 20px; }
.company-card {
  display: flex; align-items: center; justify-content: center;
  padding: 28px 20px; border-radius: var(--radius);
  background: var(--white); border: 1px solid var(--gray-200);
  font-size: 1.1rem; font-weight: 700; color: var(--gray-700);
  transition: all 0.15s; cursor: pointer;
  letter-spacing: -0.01em;
}
.company-card:hover { box-shadow: var(--shadow); border-color: var(--gray-300); }

/* ===== FAQ Accordion ===== */
.faq-list { max-width: 780px; margin: 0 auto; }
.faq-item { border-bottom: 1px solid var(--gray-200); }
.faq-question {
  width: 100%; padding: 20px 0;
  display: flex; align-items: center; justify-content: space-between;
  font-size: 1rem; font-weight: 600;
  color: var(--gray-800); text-align: left;
  transition: color 0.15s; cursor: pointer;
  font-family: inherit;
}
.faq-question:hover { color: var(--blue); }
.faq-question::after {
  content: '+'; font-size: 1.4rem; font-weight: 300;
  color: var(--gray-400); transition: transform 0.2s;
  margin-left: 16px; flex-shrink: 0;
}
.faq-item.open .faq-question::after { content: '−'; transform: rotate(180deg); }
.faq-answer {
  max-height: 0; overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}
.faq-item.open .faq-answer { max-height: 200px; padding-bottom: 20px; }
.faq-answer p { color: var(--gray-600); font-size: 0.925rem; line-height: 1.65; }

/* ===== Destination Tabs (Car Rental) ===== */
.dest-tabs {
  display: flex; flex-wrap: wrap; gap: 8px;
  margin-bottom: 28px; justify-content: center;
}
.dest-tab {
  padding: 10px 22px;
  border-radius: 24px;
  font-size: 0.9rem; font-weight: 500;
  color: var(--gray-600);
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  transition: all 0.15s; cursor: pointer;
  font-family: inherit;
}
.dest-tab:hover { border-color: var(--blue); color: var(--blue); }
.dest-tab.active { background: var(--navy); color: var(--white); border-color: var(--navy); }

/* Rental destination rows */
.rental-dest-table { width: 100%; max-width: 900px; margin: 0 auto; }
.rental-dest-row {
  display: grid; grid-template-columns: 1fr auto auto;
  align-items: center; gap: 24px;
  padding: 16px 0; border-bottom: 1px solid var(--gray-100);
  cursor: pointer; transition: background 0.15s;
}
.rental-dest-row:hover { background: var(--gray-50); margin: 0 -16px; padding: 16px; border-radius: var(--radius); }
.rental-dest-row h4 { font-size: 0.95rem; margin-bottom: 2px; }
.rental-dest-row .loc-count { font-size: 0.8rem; color: var(--gray-500); }
.rental-dest-row .price { font-weight: 700; color: var(--gray-800); }
.rental-dest-row .price-period { font-size: 0.8rem; color: var(--gray-500); }

/* ===== Attraction Cards ===== */
.attr-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.attr-card {
  border-radius: var(--radius-lg); overflow: hidden;
  background: var(--white);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-200);
  transition: all 0.2s; cursor: pointer;
}
.attr-card:hover { box-shadow: var(--shadow); transform: translateY(-2px); }
.attr-card-img {
  height: 180px;
  background: linear-gradient(135deg, #dbeafe, #c7d2fe);
  display: flex; align-items: center; justify-content: center;
}
.attr-card-img .placeholder-icon { font-size: 2.5rem; opacity: 0.4; }
.attr-card-body { padding: 16px; }
.attr-card-body h3 { font-size: 0.925rem; margin-bottom: 4px; font-weight: 600; line-height: 1.3; }
.attr-card-body .attr-meta { font-size: 0.8rem; color: var(--gray-500); }

/* Nearby destinations */
.nearby-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.nearby-card {
  position: relative; border-radius: var(--radius-lg); overflow: hidden;
  aspect-ratio: 3/2; cursor: pointer;
  background: linear-gradient(135deg, #c7d2fe, #a5b4fc);
  display: flex; align-items: flex-end; transition: transform 0.2s;
}
.nearby-card:hover { transform: translateY(-2px); }
.nearby-overlay {
  padding: 20px; width: 100%;
  background: linear-gradient(transparent, rgba(0,0,0,0.7));
  color: var(--white);
}
.nearby-overlay h3 { color: var(--white); font-size: 1rem; margin-bottom: 2px; }
.nearby-overlay span { font-size: 0.8rem; opacity: 0.85; }

/* ===== Attractions CTA ===== */
.account-cta {
  background: var(--gray-50); padding: 64px 0;
  text-align: center;
}
.account-cta h2 { margin-bottom: 4px; }
.account-cta .subtitle { color: var(--gray-500); margin-bottom: 8px; }
.account-cta p { color: var(--gray-600); margin-bottom: 20px; max-width: 500px; margin-left: auto; margin-right: auto; }

/* ===== Things to Do Tabs ===== */
.things-tabs {
  display: flex; flex-wrap: wrap; gap: 8px;
  margin-bottom: 28px; justify-content: center;
}
.things-tab {
  padding: 10px 20px;
  border-radius: 24px;
  font-size: 0.9rem; font-weight: 500;
  color: var(--gray-600);
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  transition: all 0.15s; cursor: pointer;
  font-family: inherit;
}
.things-tab:hover { border-color: var(--blue); color: var(--blue); }
.things-tab.active { background: var(--navy); color: var(--white); border-color: var(--navy); }
.things-links { display: flex; flex-wrap: wrap; gap: 12px; justify-content: center; }
.things-link-item {
  padding: 8px 16px;
  color: var(--gray-600); font-size: 0.9rem;
  transition: color 0.15s; cursor: pointer;
  text-decoration: none;
}
.things-link-item:hover { color: var(--blue); text-decoration: underline; }

/* ===== Credit Card Promo ===== */
.cc-promo {
  background: linear-gradient(135deg, #fef9e7, #fff3cd);
  padding: 48px 0; text-align: center;
}
.cc-promo h3 { font-size: 1.3rem; margin-bottom: 8px; }
.cc-promo p { color: var(--gray-600); margin-bottom: 16px; max-width: 500px; margin-left: auto; margin-right: auto; }

/* ===== Explore destinations with region tabs ===== */
.region-tabs {
  display: flex; flex-wrap: wrap; gap: 8px;
  margin-bottom: 28px; justify-content: center;
}
.region-tab {
  padding: 10px 20px;
  border-radius: 24px;
  font-size: 0.9rem; font-weight: 500;
  color: var(--gray-600);
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  transition: all 0.15s; cursor: pointer;
  font-family: inherit;
}
.region-tab:hover { border-color: var(--blue); color: var(--blue); }
.region-tab.active { background: var(--navy); color: var(--white); border-color: var(--navy); }
.explore-dest-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; }
.explore-dest-item {
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 18px;
  border-radius: var(--radius);
  background: var(--white);
  border: 1px solid var(--gray-200);
  transition: all 0.15s; cursor: pointer;
}
.explore-dest-item:hover { box-shadow: var(--shadow-sm); border-color: var(--gray-300); }
.explore-dest-item h4 { font-size: 0.925rem; font-weight: 600; }
.explore-dest-item span { font-size: 0.8rem; color: var(--gray-500); }

/* ===== Footer ===== */
.site-footer {
  background: var(--gray-900);
  color: var(--gray-400);
  padding: 64px 0 0;
}
.footer-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 40px; padding-bottom: 48px; }
.footer-col h4 { color: var(--white); font-size: 0.9rem; margin-bottom: 16px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.03em; }
.footer-col a {
  display: block; color: var(--gray-400); font-size: 0.875rem;
  padding: 4px 0; transition: color 0.15s; text-decoration: none;
}
.footer-col a:hover { color: var(--white); text-decoration: underline; }
.footer-bottom {
  border-top: 1px solid var(--gray-700);
  padding: 24px 0;
  text-align: center;
  font-size: 0.8rem;
  color: var(--gray-500);
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .trust-grid { grid-template-columns: repeat(2, 1fr); }
  .destinations-grid { grid-template-columns: repeat(3, 1fr); }
  .homes-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: repeat(2, 1fr); }
  .companies-grid { grid-template-columns: repeat(3, 1fr); }
  .explore-dest-grid { grid-template-columns: repeat(3, 1fr); }
  .trip-destinations { grid-template-columns: repeat(2, 1fr); }
  .carousel-btn--prev { left: 8px; }
  .carousel-btn--next { right: 8px; }
}

@media (max-width: 768px) {
  h1 { font-size: 1.75rem; }
  h2 { font-size: 1.35rem; }
  .section { padding: 48px 0; }
  .hero { padding: 56px 0 40px; }
  .hero h1 { font-size: 1.75rem; }
  .search-card { flex-direction: column; padding: 12px; }
  .search-field::after { display: none; }
  .search-field { width: 100%; padding: 8px 12px; border-bottom: 1px solid var(--gray-100); }
  .search-btn { width: calc(100% - 8px); }
  .trust-grid { grid-template-columns: 1fr; gap: 20px; }
  .offers-grid { grid-template-columns: 1fr; }
  .destinations-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .homes-grid { grid-template-columns: 1fr; }
  .companies-grid { grid-template-columns: repeat(2, 1fr); }
  .benefits-grid { grid-template-columns: 1fr; }
  .explore-dest-grid { grid-template-columns: repeat(2, 1fr); }
  .nearby-grid { grid-template-columns: repeat(2, 1fr); }
  .attr-cards { grid-template-columns: 1fr; }
  .trip-destinations { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 28px; }
  .carousel-btn { display: none; }
  .nav-links { display: none; }
  .nav-links.open {
    display: flex; flex-direction: column;
    position: absolute; top: var(--header-height); left: 0; right: 0;
    background: var(--navy-dark); padding: 16px;
    gap: 4px;
  }
  .mobile-menu-btn { display: block; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .destinations-grid { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .rental-dest-row { grid-template-columns: 1fr; gap: 4px; }
  .package-radios { flex-direction: column; }
}

/* ===== StayQuest Design System ===== */
:root {
  --navy: #003B95;
  --navy-dark: #002a6e;
  --navy-light: #004cb8;
  --blue: #006CE4;
  --blue-light: #e8f2fd;
  --gold: #FFB700;
  --gold-dark: #e6a500;
  --gold-light: #fff7e0;
  --white: #FFFFFF;
  --gray-50: #f8f9fa;
  --gray-100: #f0f2f5;
  --gray-200: #e4e7ec;
  --gray-300: #ced2d9;
  --gray-400: #9ba3af;
  --gray-500: #6b7280;
  --gray-600: #4b5563;
  --gray-700: #374151;
  --gray-800: #1f2937;
  --gray-900: #111827;
  --green: #059669;
  --red: #dc2626;
  --red-light: #fef2f2;
  --radius-sm: 6px;
  --radius: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.06);
  --shadow: 0 2px 8px rgba(0,0,0,0.08);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.1);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.12);
  --font: 'Inter', 'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --max-width: 1200px;
  --header-height: 68px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }

body {
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.6;
  color: var(--gray-800);
  background: var(--white);
  min-height: 100vh;
}

img { max-width: 100%; display: block; }
a { color: var(--blue); text-decoration: none; }
a:hover { text-decoration: underline; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul { list-style: none; }

/* ===== Typography ===== */
h1, h2, h3, h4 { color: var(--gray-900); line-height: 1.25; }
h1 { font-size: 2.5rem; font-weight: 800; }
h2 { font-size: 1.75rem; font-weight: 700; }
h3 { font-size: 1.25rem; font-weight: 600; }

/* ===== Layout ===== */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.section { padding: 72px 0; }
.section--alt { background: var(--gray-50); }
.section-header { text-align: center; margin-bottom: 40px; }
.section-header h2 { margin-bottom: 8px; }
.section-header p { color: var(--gray-500); font-size: 1.075rem; }

/* ===== Header / Navigation ===== */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: var(--navy);
  height: var(--header-height);
  box-shadow: 0 2px 12px rgba(0,0,0,0.15);
}
.site-header .container {
  display: flex; align-items: center; justify-content: space-between;
  height: 100%;
}
.logo {
  display: flex; align-items: center; gap: 10px;
  color: var(--white); font-size: 1.35rem; font-weight: 800;
  text-decoration: none; letter-spacing: -0.02em;
}
.logo:hover { text-decoration: none; opacity: 0.9; }
.logo-icon {
  width: 34px; height: 34px;
  background: var(--gold);
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  color: var(--navy); font-size: 1.1rem; font-weight: 900;
}
.nav-links { display: flex; align-items: center; gap: 6px; }
.nav-links a {
  color: rgba(255,255,255,0.85);
  padding: 8px 16px;
  border-radius: 24px;
  font-size: 0.9rem; font-weight: 500;
  text-decoration: none;
  transition: all 0.15s ease;
  white-space: nowrap;
}
.nav-links a:hover,
.nav-links a.active {
  color: var(--white);
  background: rgba(255,255,255,0.12);
  text-decoration: none;
}
.nav-links a.active { background: rgba(255,255,255,0.2); font-weight: 600; }
.mobile-menu-btn { display: none; color: var(--white); font-size: 1.5rem; padding: 8px; }

/* ===== Buttons ===== */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 12px 28px;
  border-radius: 28px;
  font-size: 0.95rem; font-weight: 600;
  text-decoration: none;
  transition: all 0.15s ease;
  border: 2px solid transparent;
  white-space: nowrap;
}
.btn:hover { text-decoration: none; transform: translateY(-1px); }
.btn-primary { background: var(--blue); color: var(--white); border-color: var(--blue); }
.btn-primary:hover { background: #0059c7; border-color: #0059c7; }
.btn-gold { background: var(--gold); color: var(--gray-900); border-color: var(--gold); }
.btn-gold:hover { background: var(--gold-dark); border-color: var(--gold-dark); }
.btn-outline { background: transparent; color: var(--navy); border-color: var(--navy); }
.btn-outline:hover { background: var(--navy); color: var(--white); }
.btn-white { background: var(--white); color: var(--navy); }
.btn-white:hover { background: var(--gray-100); }
.btn-sm { padding: 8px 18px; font-size: 0.85rem; }

/* ===== Hero Section ===== */
.hero {
  background: linear-gradient(135deg, var(--navy) 0%, #002766 50%, var(--navy-dark) 100%);
  color: var(--white);
  padding: 80px 0 64px;
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at 30% 50%, rgba(0,108,228,0.25) 0%, transparent 60%),
              radial-gradient(ellipse at 70% 20%, rgba(255,183,0,0.1) 0%, transparent 50%);
  pointer-events: none;
}
.hero .container { position: relative; z-index: 1; }
.hero-content { text-align: center; max-width: 720px; margin: 0 auto 36px; }
.hero h1 { font-size: 2.75rem; color: var(--white); margin-bottom: 8px; }
.hero p { font-size: 1.15rem; color: rgba(255,255,255,0.8); }

.search-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 6px;
  box-shadow: var(--shadow-lg);
  max-width: 920px;
  margin: 0 auto;
  display: flex; align-items: center; gap: 4px;
  flex-wrap: wrap;
  position: relative;
}
.search-field {
  flex: 1; min-width: 140px;
  position: relative;
  padding: 10px 14px;
  border-radius: var(--radius);
  transition: background 0.15s;
}
.search-field:hover { background: var(--gray-50); }
.search-field:not(:last-child)::after {
  content: ''; position: absolute; right: 0; top: 20%; height: 60%;
  width: 1px; background: var(--gray-200);
}
.search-label {
  display: block; font-size: 0.75rem; font-weight: 600;
  color: var(--gray-500); text-transform: uppercase; letter-spacing: 0.04em;
  margin-bottom: 2px;
}
.search-input {
  width: 100%; border: none; outline: none;
  font-size: 0.925rem; color: var(--gray-800);
  background: transparent; font-family: inherit;
}
.search-input::placeholder { color: var(--gray-400); }
.search-btn {
  padding: 14px 32px;
  border-radius: 28px;
  font-size: 1rem; font-weight: 700;
  margin: 4px;
  flex-shrink: 0;
}
.search-extra {
  max-width: 920px; margin: 12px auto 0;
  display: flex; align-items: center; gap: 8px;
}
.search-extra label {
  display: flex; align-items: center; gap: 8px;
  color: rgba(255,255,255,0.9); font-size: 0.9rem; cursor: pointer;
}
.search-extra input[type="checkbox"] {
  width: 18px; height: 18px; accent-color: var(--gold); cursor: pointer;
}

/* Package radio group */
.package-radios {
  display: flex; flex-wrap: wrap; gap: 6px;
  max-width: 920px; margin: 0 auto 16px;
}
.package-radio-label {
  display: flex; align-items: center; gap: 8px;
  padding: 10px 18px;
  border-radius: 24px;
  background: rgba(255,255,255,0.1);
  color: rgba(255,255,255,0.9);
  font-size: 0.875rem; font-weight: 500;
  cursor: pointer; transition: all 0.15s;
  border: 2px solid transparent;
}
.package-radio-label:hover { background: rgba(255,255,255,0.18); }
.package-radio-label.active {
  background: var(--white);
  color: var(--navy);
  border-color: var(--white);
  font-weight: 600;
}
.package-radio-label input { display: none; }

/* Car rental extra options */
.search-checkboxes {
  max-width: 920px; margin: 12px auto 0;
  display: flex; flex-wrap: wrap; gap: 20px;
}

/* ===== Trust Badges ===== */
.trust-badges { padding: 48px 0; border-bottom: 1px solid var(--gray-200); }
.trust-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px;
}
.trust-item {
  display: flex; align-items: flex-start; gap: 14px;
}
.trust-icon {
  width: 44px; height: 44px; border-radius: var(--radius);
  background: var(--blue-light);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0; font-size: 1.3rem;
}
.trust-item h4 { font-size: 0.95rem; margin-bottom: 2px; font-weight: 600; }
.trust-item p { font-size: 0.85rem; color: var(--gray-500); }

/* ===== Offers ===== */
.offers-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.offer-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 36px; position: relative; overflow: hidden;
  box-shadow: var(--shadow);
  border: 1px solid var(--gray-200);
}
.offer-card--deal { background: linear-gradient(135deg, #fef9e7, #fff3cd); border-color: #f0d77b; }
.offer-card--credit { background: linear-gradient(135deg, #eff6ff, #dbeafe); border-color: #bdd5f5; }
.offer-card h3 { font-size: 1.35rem; margin-bottom: 8px; }
.offer-card p { color: var(--gray-600); margin-bottom: 20px; max-width: 400px; }

/* ===== Property Types ===== */
.property-types-list {
  display: flex; flex-wrap: wrap; gap: 10px;
  justify-content: center;
}
.property-type-tag {
  padding: 10px 20px;
  border-radius: 24px;
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  color: var(--gray-700);
  font-size: 0.875rem; font-weight: 500;
  transition: all 0.15s;
  cursor: pointer;
}
.property-type-tag:hover { border-color: var(--blue); color: var(--blue); background: var(--blue-light); }

/* ===== Trip Planner ===== */
.trip-planner-tabs {
  display: flex; flex-wrap: nowrap; gap: 0;
  overflow-x: auto;
  border-bottom: 2px solid var(--gray-200);
  margin-bottom: 32px;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.trip-planner-tabs::-webkit-scrollbar { display: none; }
.trip-planner-tab {
  padding: 12px 20px;
  font-size: 0.9rem; font-weight: 500;
  color: var(--gray-500);
  white-space: nowrap;
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
  transition: all 0.15s;
  cursor: pointer;
  background: none;
  font-family: inherit;
}
.trip-planner-tab:hover { color: var(--gray-700); }
.trip-planner-tab.active {
  color: var(--navy); font-weight: 600;
  border-bottom-color: var(--blue);
}
.trip-destinations {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px;
}
.trip-destination-card {
  display: flex; align-items: center; gap: 14px;
  padding: 16px; border-radius: var(--radius);
  border: 1px solid var(--gray-200);
  transition: all 0.15s; cursor: pointer;
}
.trip-destination-card:hover { box-shadow: var(--shadow); border-color: var(--gray-300); }
.trip-dest-img {
  width: 64px; height: 64px; border-radius: var(--radius-sm);
  background: linear-gradient(135deg, var(--blue-light), #d0e2ff);
  flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem;
}
.trip-dest-info h4 { font-size: 0.95rem; margin-bottom: 2px; }
.trip-dest-info span { font-size: 0.8rem; color: var(--gray-500); }

/* ===== Unique Properties Carousel ===== */
.carousel-wrapper { position: relative; }
.carousel-container { overflow-x: auto; scroll-snap-type: x mandatory; -webkit-overflow-scrolling: touch; scrollbar-width: none; }
.carousel-container::-webkit-scrollbar { display: none; }
.carousel-track { display: flex; gap: 20px; }
.carousel-btn {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 44px; height: 44px; border-radius: 50%;
  background: var(--white); box-shadow: var(--shadow-md);
  display: flex; align-items: center; justify-content: center;
  z-index: 10; font-size: 1.2rem; color: var(--gray-700);
  transition: all 0.15s;
}
.carousel-btn:hover { box-shadow: var(--shadow-lg); background: var(--gray-50); }
.carousel-btn--prev { left: -16px; }
.carousel-btn--next { right: -16px; }

/* ===== Property Cards ===== */
.property-card {
  flex: 0 0 calc(33.333% - 14px); min-width: 280px;
  border-radius: var(--radius-lg); overflow: hidden;
  background: var(--white); box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-200);
  transition: all 0.2s; cursor: pointer;
  scroll-snap-align: start;
}
.property-card:hover { box-shadow: var(--shadow); transform: translateY(-2px); }
.property-img {
  height: 200px; position: relative;
  background: linear-gradient(135deg, #dbeafe, #bfdbfe);
  display: flex; align-items: center; justify-content: center;
}
.property-img .placeholder-icon { font-size: 3rem; opacity: 0.4; }
.property-img .rating-badge {
  position: absolute; top: 12px; right: 12px;
  background: var(--navy); color: var(--white);
  padding: 4px 10px; border-radius: 12px;
  font-size: 0.8rem; font-weight: 700;
}
.property-body { padding: 16px; }
.property-body h3 { font-size: 0.95rem; margin-bottom: 4px; line-height: 1.3; font-weight: 600; }
.property-body .location { color: var(--gray-500); font-size: 0.85rem; margin-bottom: 8px; }
.property-body .meta { display: flex; align-items: center; gap: 12px; font-size: 0.8rem; color: var(--gray-500); margin-bottom: 10px; }
.property-body .meta .rating { font-weight: 700; color: var(--navy); }
.property-body .meta .reviews { color: var(--gray-400); }
.property-footer { display: flex; align-items: baseline; justify-content: space-between; padding-top: 10px; border-top: 1px solid var(--gray-100); }
.property-footer .price { font-size: 1.15rem; font-weight: 700; color: var(--gray-900); }
.property-footer .price-period { font-size: 0.8rem; color: var(--gray-500); }
.property-footer .old-price { text-decoration: line-through; color: var(--gray-400); font-size: 0.85rem; margin-right: 6px; }
.property-footer .sale-badge { background: var(--red-light); color: var(--red); padding: 3px 8px; border-radius: 4px; font-size: 0.75rem; font-weight: 600; }

/* ===== Trending / Explore Destinations ===== */
.trending-tags { display: flex; flex-wrap: wrap; gap: 12px; justify-content: center; }
.trending-tag {
  padding: 10px 22px;
  border-radius: 24px;
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  color: var(--gray-700);
  font-size: 0.9rem; font-weight: 500;
  transition: all 0.15s; cursor: pointer;
}
.trending-tag:hover { border-color: var(--blue); color: var(--blue); background: var(--blue-light); }

.destinations-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px; }
.dest-card {
  position: relative; border-radius: var(--radius-lg); overflow: hidden;
  aspect-ratio: 4/5; cursor: pointer;
  background: linear-gradient(135deg, #e0e7ff, #c7d2fe);
  display: flex; align-items: flex-end;
  transition: transform 0.2s;
}
.dest-card:hover { transform: translateY(-2px); }
.dest-card-overlay {
  padding: 20px; width: 100%;
  background: linear-gradient(transparent, rgba(0,0,0,0.7));
  color: var(--white);
}
.dest-card-overlay h3 { color: var(--white); font-size: 1rem; margin-bottom: 2px; }
.dest-card-overlay span { font-size: 0.8rem; opacity: 0.85; }

/* ===== Deal Cards (weekend deals variant) ===== */
.deals-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }

/* ===== Homes Guests Love ===== */
.homes-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
.homes-cta { text-align: center; margin-top: 32px; }

/* ===== Loyalty CTA ===== */
.loyalty-cta {
  background: linear-gradient(135deg, var(--navy) 0%, #002766 100%);
  color: var(--white); padding: 72px 0;
}
.loyalty-content { text-align: center; max-width: 600px; margin: 0 auto; }
.loyalty-content h2 { color: var(--white); font-size: 2rem; margin-bottom: 8px; }
.loyalty-content .subhead { color: var(--gold); font-weight: 600; margin-bottom: 12px; font-size: 1.05rem; }
.loyalty-content p { color: rgba(255,255,255,0.8); margin-bottom: 24px; }
.loyalty-buttons { display: flex; gap: 12px; justify-content: center; }

/* ===== Popular Links Tabs ===== */
.popular-tabs {
  display: flex; flex-wrap: wrap; gap: 8px;
  margin-bottom: 28px; justify-content: center;
}
.popular-tab {
  padding: 10px 22px;
  border-radius: 24px;
  font-size: 0.9rem; font-weight: 500;
  color: var(--gray-600);
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  transition: all 0.15s; cursor: pointer;
  font-family: inherit;
}
.popular-tab:hover { border-color: var(--blue); color: var(--blue); }
.popular-tab.active { background: var(--navy); color: var(--white); border-color: var(--navy); }
.popular-links-list {
  display: flex; flex-wrap: wrap; gap: 12px;
  justify-content: center;
}
.popular-link-item {
  padding: 8px 16px;
  color: var(--gray-600); font-size: 0.9rem;
  transition: color 0.15s; cursor: pointer;
  text-decoration: none;
}
.popular-link-item:hover { color: var(--blue); text-decoration: underline; }

/* ===== Benefits Section ===== */
.benefits-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
.benefit-card {
  text-align: center; padding: 36px 24px;
  border-radius: var(--radius-lg);
  background: var(--white);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-200);
}
.benefit-icon {
  width: 56px; height: 56px; border-radius: 50%;
  background: var(--blue-light); margin: 0 auto 16px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem;
}
.benefit-card h3 { margin-bottom: 8px; }
.benefit-card p { color: var(--gray-500); font-size: 0.925rem; }

/* ===== Companies Grid (Car Rental) ===== */
.companies-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 20px; }
.company-card {
  display: flex; align-items: center; justify-content: center;
  padding: 28px 20px; border-radius: var(--radius);
  background: var(--white); border: 1px solid var(--gray-200);
  font-size: 1.1rem; font-weight: 700; color: var(--gray-700);
  transition: all 0.15s; cursor: pointer;
  letter-spacing: -0.01em;
}
.company-card:hover { box-shadow: var(--shadow); border-color: var(--gray-300); }

/* ===== FAQ Accordion ===== */
.faq-list { max-width: 780px; margin: 0 auto; }
.faq-item { border-bottom: 1px solid var(--gray-200); }
.faq-question {
  width: 100%; padding: 20px 0;
  display: flex; align-items: center; justify-content: space-between;
  font-size: 1rem; font-weight: 600;
  color: var(--gray-800); text-align: left;
  transition: color 0.15s; cursor: pointer;
  font-family: inherit;
}
.faq-question:hover { color: var(--blue); }
.faq-question::after {
  content: '+'; font-size: 1.4rem; font-weight: 300;
  color: var(--gray-400); transition: transform 0.2s;
  margin-left: 16px; flex-shrink: 0;
}
.faq-item.open .faq-question::after { content: '−'; transform: rotate(180deg); }
.faq-answer {
  max-height: 0; overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}
.faq-item.open .faq-answer { max-height: 200px; padding-bottom: 20px; }
.faq-answer p { color: var(--gray-600); font-size: 0.925rem; line-height: 1.65; }

/* ===== Destination Tabs (Car Rental) ===== */
.dest-tabs {
  display: flex; flex-wrap: wrap; gap: 8px;
  margin-bottom: 28px; justify-content: center;
}
.dest-tab {
  padding: 10px 22px;
  border-radius: 24px;
  font-size: 0.9rem; font-weight: 500;
  color: var(--gray-600);
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  transition: all 0.15s; cursor: pointer;
  font-family: inherit;
}
.dest-tab:hover { border-color: var(--blue); color: var(--blue); }
.dest-tab.active { background: var(--navy); color: var(--white); border-color: var(--navy); }

/* Rental destination rows */
.rental-dest-table { width: 100%; max-width: 900px; margin: 0 auto; }
.rental-dest-row {
  display: grid; grid-template-columns: 1fr auto auto;
  align-items: center; gap: 24px;
  padding: 16px 0; border-bottom: 1px solid var(--gray-100);
  cursor: pointer; transition: background 0.15s;
}
.rental-dest-row:hover { background: var(--gray-50); margin: 0 -16px; padding: 16px; border-radius: var(--radius); }
.rental-dest-row h4 { font-size: 0.95rem; margin-bottom: 2px; }
.rental-dest-row .loc-count { font-size: 0.8rem; color: var(--gray-500); }
.rental-dest-row .price { font-weight: 700; color: var(--gray-800); }
.rental-dest-row .price-period { font-size: 0.8rem; color: var(--gray-500); }

/* ===== Attraction Cards ===== */
.attr-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.attr-card {
  border-radius: var(--radius-lg); overflow: hidden;
  background: var(--white);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-200);
  transition: all 0.2s; cursor: pointer;
}
.attr-card:hover { box-shadow: var(--shadow); transform: translateY(-2px); }
.attr-card-img {
  height: 180px;
  background: linear-gradient(135deg, #dbeafe, #c7d2fe);
  display: flex; align-items: center; justify-content: center;
}
.attr-card-img .placeholder-icon { font-size: 2.5rem; opacity: 0.4; }
.attr-card-body { padding: 16px; }
.attr-card-body h3 { font-size: 0.925rem; margin-bottom: 4px; font-weight: 600; line-height: 1.3; }
.attr-card-body .attr-meta { font-size: 0.8rem; color: var(--gray-500); }

/* Nearby destinations */
.nearby-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.nearby-card {
  position: relative; border-radius: var(--radius-lg); overflow: hidden;
  aspect-ratio: 3/2; cursor: pointer;
  background: linear-gradient(135deg, #c7d2fe, #a5b4fc);
  display: flex; align-items: flex-end; transition: transform 0.2s;
}
.nearby-card:hover { transform: translateY(-2px); }
.nearby-overlay {
  padding: 20px; width: 100%;
  background: linear-gradient(transparent, rgba(0,0,0,0.7));
  color: var(--white);
}
.nearby-overlay h3 { color: var(--white); font-size: 1rem; margin-bottom: 2px; }
.nearby-overlay span { font-size: 0.8rem; opacity: 0.85; }

/* ===== Attractions CTA ===== */
.account-cta {
  background: var(--gray-50); padding: 64px 0;
  text-align: center;
}
.account-cta h2 { margin-bottom: 4px; }
.account-cta .subtitle { color: var(--gray-500); margin-bottom: 8px; }
.account-cta p { color: var(--gray-600); margin-bottom: 20px; max-width: 500px; margin-left: auto; margin-right: auto; }

/* ===== Things to Do Tabs ===== */
.things-tabs {
  display: flex; flex-wrap: wrap; gap: 8px;
  margin-bottom: 28px; justify-content: center;
}
.things-tab {
  padding: 10px 20px;
  border-radius: 24px;
  font-size: 0.9rem; font-weight: 500;
  color: var(--gray-600);
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  transition: all 0.15s; cursor: pointer;
  font-family: inherit;
}
.things-tab:hover { border-color: var(--blue); color: var(--blue); }
.things-tab.active { background: var(--navy); color: var(--white); border-color: var(--navy); }
.things-links { display: flex; flex-wrap: wrap; gap: 12px; justify-content: center; }
.things-link-item {
  padding: 8px 16px;
  color: var(--gray-600); font-size: 0.9rem;
  transition: color 0.15s; cursor: pointer;
  text-decoration: none;
}
.things-link-item:hover { color: var(--blue); text-decoration: underline; }

/* ===== Credit Card Promo ===== */
.cc-promo {
  background: linear-gradient(135deg, #fef9e7, #fff3cd);
  padding: 48px 0; text-align: center;
}
.cc-promo h3 { font-size: 1.3rem; margin-bottom: 8px; }
.cc-promo p { color: var(--gray-600); margin-bottom: 16px; max-width: 500px; margin-left: auto; margin-right: auto; }

/* ===== Explore destinations with region tabs ===== */
.region-tabs {
  display: flex; flex-wrap: wrap; gap: 8px;
  margin-bottom: 28px; justify-content: center;
}
.region-tab {
  padding: 10px 20px;
  border-radius: 24px;
  font-size: 0.9rem; font-weight: 500;
  color: var(--gray-600);
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  transition: all 0.15s; cursor: pointer;
  font-family: inherit;
}
.region-tab:hover { border-color: var(--blue); color: var(--blue); }
.region-tab.active { background: var(--navy); color: var(--white); border-color: var(--navy); }
.explore-dest-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; }
.explore-dest-item {
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 18px;
  border-radius: var(--radius);
  background: var(--white);
  border: 1px solid var(--gray-200);
  transition: all 0.15s; cursor: pointer;
}
.explore-dest-item:hover { box-shadow: var(--shadow-sm); border-color: var(--gray-300); }
.explore-dest-item h4 { font-size: 0.925rem; font-weight: 600; }
.explore-dest-item span { font-size: 0.8rem; color: var(--gray-500); }

/* ===== Footer ===== */
.site-footer {
  background: var(--gray-900);
  color: var(--gray-400);
  padding: 64px 0 0;
}
.footer-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 40px; padding-bottom: 48px; }
.footer-col h4 { color: var(--white); font-size: 0.9rem; margin-bottom: 16px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.03em; }
.footer-col a {
  display: block; color: var(--gray-400); font-size: 0.875rem;
  padding: 4px 0; transition: color 0.15s; text-decoration: none;
}
.footer-col a:hover { color: var(--white); text-decoration: underline; }
.footer-bottom {
  border-top: 1px solid var(--gray-700);
  padding: 24px 0;
  text-align: center;
  font-size: 0.8rem;
  color: var(--gray-500);
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .trust-grid { grid-template-columns: repeat(2, 1fr); }
  .destinations-grid { grid-template-columns: repeat(3, 1fr); }
  .homes-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: repeat(2, 1fr); }
  .companies-grid { grid-template-columns: repeat(3, 1fr); }
  .explore-dest-grid { grid-template-columns: repeat(3, 1fr); }
  .trip-destinations { grid-template-columns: repeat(2, 1fr); }
  .carousel-btn--prev { left: 8px; }
  .carousel-btn--next { right: 8px; }
}

@media (max-width: 768px) {
  h1 { font-size: 1.75rem; }
  h2 { font-size: 1.35rem; }
  .section { padding: 48px 0; }
  .hero { padding: 56px 0 40px; }
  .hero h1 { font-size: 1.75rem; }
  .search-card { flex-direction: column; padding: 12px; }
  .search-field::after { display: none; }
  .search-field { width: 100%; padding: 8px 12px; border-bottom: 1px solid var(--gray-100); }
  .search-btn { width: calc(100% - 8px); }
  .trust-grid { grid-template-columns: 1fr; gap: 20px; }
  .offers-grid { grid-template-columns: 1fr; }
  .destinations-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .homes-grid { grid-template-columns: 1fr; }
  .companies-grid { grid-template-columns: repeat(2, 1fr); }
  .benefits-grid { grid-template-columns: 1fr; }
  .explore-dest-grid { grid-template-columns: repeat(2, 1fr); }
  .nearby-grid { grid-template-columns: repeat(2, 1fr); }
  .attr-cards { grid-template-columns: 1fr; }
  .trip-destinations { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 28px; }
  .carousel-btn { display: none; }
  .nav-links { display: none; }
  .nav-links.open {
    display: flex; flex-direction: column;
    position: absolute; top: var(--header-height); left: 0; right: 0;
    background: var(--navy-dark); padding: 16px;
    gap: 4px;
  }
  .mobile-menu-btn { display: block; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .destinations-grid { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .rental-dest-row { grid-template-columns: 1fr; gap: 4px; }
  .package-radios { flex-direction: column; }
}

raw_arguments.content:
/* ===== StayQuest Design System ===== */
:root {
  --navy: #003B95;
  --navy-dark: #002a6e;
  --navy-light: #004cb8;
  --blue: #006CE4;
  --blue-light: #e8f2fd;
  --gold: #FFB700;
  --gold-dark: #e6a500;
  --gold-light: #fff7e0;
  --white: #FFFFFF;
  --gray-50: #f8f9fa;
  --gray-100: #f0f2f5;
  --gray-200: #e4e7ec;
  --gray-300: #ced2d9;
  --gray-400: #9ba3af;
  --gray-500: #6b7280;
  --gray-600: #4b5563;
  --gray-700: #374151;
  --gray-800: #1f2937;
  --gray-900: #111827;
  --green: #059669;
  --red: #dc2626;
  --red-light: #fef2f2;
  --radius-sm: 6px;
  --radius: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.06);
  --shadow: 0 2px 8px rgba(0,0,0,0.08);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.1);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.12);
  --font: 'Inter', 'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --max-width: 1200px;
  --header-height: 68px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }

body {
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.6;
  color: var(--gray-800);
  background: var(--white);
  min-height: 100vh;
}

img { max-width: 100%; display: block; }
a { color: var(--blue); text-decoration: none; }
a:hover { text-decoration: underline; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul { list-style: none; }

/* ===== Typography ===== */
h1, h2, h3, h4 { color: var(--gray-900); line-height: 1.25; }
h1 { font-size: 2.5rem; font-weight: 800; }
h2 { font-size: 1.75rem; font-weight: 700; }
h3 { font-size: 1.25rem; font-weight: 600; }

/* ===== Layout ===== */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.section { padding: 72px 0; }
.section--alt { background: var(--gray-50); }
.section-header { text-align: center; margin-bottom: 40px; }
.section-header h2 { margin-bottom: 8px; }
.section-header p { color: var(--gray-500); font-size: 1.075rem; }

/* ===== Header / Navigation ===== */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: var(--navy);
  height: var(--header-height);
  box-shadow: 0 2px 12px rgba(0,0,0,0.15);
}
.site-header .container {
  display: flex; align-items: center; justify-content: space-between;
  height: 100%;
}
.logo {
  display: flex; align-items: center; gap: 10px;
  color: var(--white); font-size: 1.35rem; font-weight: 800;
  text-decoration: none; letter-spacing: -0.02em;
}
.logo:hover { text-decoration: none; opacity: 0.9; }
.logo-icon {
  width: 34px; height: 34px;
  background: var(--gold);
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  color: var(--navy); font-size: 1.1rem; font-weight: 900;
}
.nav-links { display: flex; align-items: center; gap: 6px; }
.nav-links a {
  color: rgba(255,255,255,0.85);
  padding: 8px 16px;
  border-radius: 24px;
  font-size: 0.9rem; font-weight: 500;
  text-decoration: none;
  transition: all 0.15s ease;
  white-space: nowrap;
}
.nav-links a:hover,
.nav-links a.active {
  color: var(--white);
  background: rgba(255,255,255,0.12);
  text-decoration: none;
}
.nav-links a.active { background: rgba(255,255,255,0.2); font-weight: 600; }
.mobile-menu-btn { display: none; color: var(--white); font-size: 1.5rem; padding: 8px; }

/* ===== Buttons ===== */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 12px 28px;
  border-radius: 28px;
  font-size: 0.95rem; font-weight: 600;
  text-decoration: none;
  transition: all 0.15s ease;
  border: 2px solid transparent;
  white-space: nowrap;
}
.btn:hover { text-decoration: none; transform: translateY(-1px); }
.btn-primary { background: var(--blue); color: var(--white); border-color: var(--blue); }
.btn-primary:hover { background: #0059c7; border-color: #0059c7; }
.btn-gold { background: var(--gold); color: var(--gray-900); border-color: var(--gold); }
.btn-gold:hover { background: var(--gold-dark); border-color: var(--gold-dark); }
.btn-outline { background: transparent; color: var(--navy); border-color: var(--navy); }
.btn-outline:hover { background: var(--navy); color: var(--white); }
.btn-white { background: var(--white); color: var(--navy); }
.btn-white:hover { background: var(--gray-100); }
.btn-sm { padding: 8px 18px; font-size: 0.85rem; }

/* ===== Hero Section ===== */
.hero {
  background: linear-gradient(135deg, var(--navy) 0%, #002766 50%, var(--navy-dark) 100%);
  color: var(--white);
  padding: 80px 0 64px;
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at 30% 50%, rgba(0,108,228,0.25) 0%, transparent 60%),
              radial-gradient(ellipse at 70% 20%, rgba(255,183,0,0.1) 0%, transparent 50%);
  pointer-events: none;
}
.hero .container { position: relative; z-index: 1; }
.hero-content { text-align: center; max-width: 720px; margin: 0 auto 36px; }
.hero h1 { font-size: 2.75rem; color: var(--white); margin-bottom: 8px; }
.hero p { font-size: 1.15rem; color: rgba(255,255,255,0.8); }

.search-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 6px;
  box-shadow: var(--shadow-lg);
  max-width: 920px;
  margin: 0 auto;
  display: flex; align-items: center; gap: 4px;
  flex-wrap: wrap;
  position: relative;
}
.search-field {
  flex: 1; min-width: 140px;
  position: relative;
  padding: 10px 14px;
  border-radius: var(--radius);
  transition: background 0.15s;
}
.search-field:hover { background: var(--gray-50); }
.search-field:not(:last-child)::after {
  content: ''; position: absolute; right: 0; top: 20%; height: 60%;
  width: 1px; background: var(--gray-200);
}
.search-label {
  display: block; font-size: 0.75rem; font-weight: 600;
  color: var(--gray-500); text-transform: uppercase; letter-spacing: 0.04em;
  margin-bottom: 2px;
}
.search-input {
  width: 100%; border: none; outline: none;
  font-size: 0.925rem; color: var(--gray-800);
  background: transparent; font-family: inherit;
}
.search-input::placeholder { color: var(--gray-400); }
.search-btn {
  padding: 14px 32px;
  border-radius: 28px;
  font-size: 1rem; font-weight: 700;
  margin: 4px;
  flex-shrink: 0;
}
.search-extra {
  max-width: 920px; margin: 12px auto 0;
  display: flex; align-items: center; gap: 8px;
}
.search-extra label {
  display: flex; align-items: center; gap: 8px;
  color: rgba(255,255,255,0.9); font-size: 0.9rem; cursor: pointer;
}
.search-extra input[type="checkbox"] {
  width: 18px; height: 18px; accent-color: var(--gold); cursor: pointer;
}

/* Package radio group */
.package-radios {
  display: flex; flex-wrap: wrap; gap: 6px;
  max-width: 920px; margin: 0 auto 16px;
}
.package-radio-label {
  display: flex; align-items: center; gap: 8px;
  padding: 10px 18px;
  border-radius: 24px;
  background: rgba(255,255,255,0.1);
  color: rgba(255,255,255,0.9);
  font-size: 0.875rem; font-weight: 500;
  cursor: pointer; transition: all 0.15s;
  border: 2px solid transparent;
}
.package-radio-label:hover { background: rgba(255,255,255,0.18); }
.package-radio-label.active {
  background: var(--white);
  color: var(--navy);
  border-color: var(--white);
  font-weight: 600;
}
.package-radio-label input { display: none; }

/* Car rental extra options */
.search-checkboxes {
  max-width: 920px; margin: 12px auto 0;
  display: flex; flex-wrap: wrap; gap: 20px;
}

/* ===== Trust Badges ===== */
.trust-badges { padding: 48px 0; border-bottom: 1px solid var(--gray-200); }
.trust-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px;
}
.trust-item {
  display: flex; align-items: flex-start; gap: 14px;
}
.trust-icon {
  width: 44px; height: 44px; border-radius: var(--radius);
  background: var(--blue-light);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0; font-size: 1.3rem;
}
.trust-item h4 { font-size: 0.95rem; margin-bottom: 2px; font-weight: 600; }
.trust-item p { font-size: 0.85rem; color: var(--gray-500); }

/* ===== Offers ===== */
.offers-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.offer-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 36px; position: relative; overflow: hidden;
  box-shadow: var(--shadow);
  border: 1px solid var(--gray-200);
}
.offer-card--deal { background: linear-gradient(135deg, #fef9e7, #fff3cd); border-color: #f0d77b; }
.offer-card--credit { background: linear-gradient(135deg, #eff6ff, #dbeafe); border-color: #bdd5f5; }
.offer-card h3 { font-size: 1.35rem; margin-bottom: 8px; }
.offer-card p { color: var(--gray-600); margin-bottom: 20px; max-width: 400px; }

/* ===== Property Types ===== */
.property-types-list {
  display: flex; flex-wrap: wrap; gap: 10px;
  justify-content: center;
}
.property-type-tag {
  padding: 10px 20px;
  border-radius: 24px;
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  color: var(--gray-700);
  font-size: 0.875rem; font-weight: 500;
  transition: all 0.15s;
  cursor: pointer;
}
.property-type-tag:hover { border-color: var(--blue); color: var(--blue); background: var(--blue-light); }

/* ===== Trip Planner ===== */
.trip-planner-tabs {
  display: flex; flex-wrap: nowrap; gap: 0;
  overflow-x: auto;
  border-bottom: 2px solid var(--gray-200);
  margin-bottom: 32px;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.trip-planner-tabs::-webkit-scrollbar { display: none; }
.trip-planner-tab {
  padding: 12px 20px;
  font-size: 0.9rem; font-weight: 500;
  color: var(--gray-500);
  white-space: nowrap;
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
  transition: all 0.15s;
  cursor: pointer;
  background: none;
  font-family: inherit;
}
.trip-planner-tab:hover { color: var(--gray-700); }
.trip-planner-tab.active {
  color: var(--navy); font-weight: 600;
  border-bottom-color: var(--blue);
}
.trip-destinations {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px;
}
.trip-destination-card {
  display: flex; align-items: center; gap: 14px;
  padding: 16px; border-radius: var(--radius);
  border: 1px solid var(--gray-200);
  transition: all 0.15s; cursor: pointer;
}
.trip-destination-card:hover { box-shadow: var(--shadow); border-color: var(--gray-300); }
.trip-dest-img {
  width: 64px; height: 64px; border-radius: var(--radius-sm);
  background: linear-gradient(135deg, var(--blue-light), #d0e2ff);
  flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem;
}
.trip-dest-info h4 { font-size: 0.95rem; margin-bottom: 2px; }
.trip-dest-info span { font-size: 0.8rem; color: var(--gray-500); }

/* ===== Unique Properties Carousel ===== */
.carousel-wrapper { position: relative; }
.carousel-container { overflow-x: auto; scroll-snap-type: x mandatory; -webkit-overflow-scrolling: touch; scrollbar-width: none; }
.carousel-container::-webkit-scrollbar { display: none; }
.carousel-track { display: flex; gap: 20px; }
.carousel-btn {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 44px; height: 44px; border-radius: 50%;
  background: var(--white); box-shadow: var(--shadow-md);
  display: flex; align-items: center; justify-content: center;
  z-index: 10; font-size: 1.2rem; color: var(--gray-700);
  transition: all 0.15s;
}
.carousel-btn:hover { box-shadow: var(--shadow-lg); background: var(--gray-50); }
.carousel-btn--prev { left: -16px; }
.carousel-btn--next { right: -16px; }

/* ===== Property Cards ===== */
.property-card {
  flex: 0 0 calc(33.333% - 14px); min-width: 280px;
  border-radius: var(--radius-lg); overflow: hidden;
  background: var(--white); box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-200);
  transition: all 0.2s; cursor: pointer;
  scroll-snap-align: start;
}
.property-card:hover { box-shadow: var(--shadow); transform: translateY(-2px); }
.property-img {
  height: 200px; position: relative;
  background: linear-gradient(135deg, #dbeafe, #bfdbfe);
  display: flex; align-items: center; justify-content: center;
}
.property-img .placeholder-icon { font-size: 3rem; opacity: 0.4; }
.property-img .rating-badge {
  position: absolute; top: 12px; right: 12px;
  background: var(--navy); color: var(--white);
  padding: 4px 10px; border-radius: 12px;
  font-size: 0.8rem; font-weight: 700;
}
.property-body { padding: 16px; }
.property-body h3 { font-size: 0.95rem; margin-bottom: 4px; line-height: 1.3; font-weight: 600; }
.property-body .location { color: var(--gray-500); font-size: 0.85rem; margin-bottom: 8px; }
.property-body .meta { display: flex; align-items: center; gap: 12px; font-size: 0.8rem; color: var(--gray-500); margin-bottom: 10px; }
.property-body .meta .rating { font-weight: 700; color: var(--navy); }
.property-body .meta .reviews { color: var(--gray-400); }
.property-footer { display: flex; align-items: baseline; justify-content: space-between; padding-top: 10px; border-top: 1px solid var(--gray-100); }
.property-footer .price { font-size: 1.15rem; font-weight: 700; color: var(--gray-900); }
.property-footer .price-period { font-size: 0.8rem; color: var(--gray-500); }
.property-footer .old-price { text-decoration: line-through; color: var(--gray-400); font-size: 0.85rem; margin-right: 6px; }
.property-footer .sale-badge { background: var(--red-light); color: var(--red); padding: 3px 8px; border-radius: 4px; font-size: 0.75rem; font-weight: 600; }

/* ===== Trending / Explore Destinations ===== */
.trending-tags { display: flex; flex-wrap: wrap; gap: 12px; justify-content: center; }
.trending-tag {
  padding: 10px 22px;
  border-radius: 24px;
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  color: var(--gray-700);
  font-size: 0.9rem; font-weight: 500;
  transition: all 0.15s; cursor: pointer;
}
.trending-tag:hover { border-color: var(--blue); color: var(--blue); background: var(--blue-light); }

.destinations-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px; }
.dest-card {
  position: relative; border-radius: var(--radius-lg); overflow: hidden;
  aspect-ratio: 4/5; cursor: pointer;
  background: linear-gradient(135deg, #e0e7ff, #c7d2fe);
  display: flex; align-items: flex-end;
  transition: transform 0.2s;
}
.dest-card:hover { transform: translateY(-2px); }
.dest-card-overlay {
  padding: 20px; width: 100%;
  background: linear-gradient(transparent, rgba(0,0,0,0.7));
  color: var(--white);
}
.dest-card-overlay h3 { color: var(--white); font-size: 1rem; margin-bottom: 2px; }
.dest-card-overlay span { font-size: 0.8rem; opacity: 0.85; }

/* ===== Deal Cards (weekend deals variant) ===== */
.deals-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }

/* ===== Homes Guests Love ===== */
.homes-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
.homes-cta { text-align: center; margin-top: 32px; }

/* ===== Loyalty CTA ===== */
.loyalty-cta {
  background: linear-gradient(135deg, var(--navy) 0%, #002766 100%);
  color: var(--white); padding: 72px 0;
}
.loyalty-content { text-align: center; max-width: 600px; margin: 0 auto; }
.loyalty-content h2 { color: var(--white); font-size: 2rem; margin-bottom: 8px; }
.loyalty-content .subhead { color: var(--gold); font-weight: 600; margin-bottom: 12px; font-size: 1.05rem; }
.loyalty-content p { color: rgba(255,255,255,0.8); margin-bottom: 24px; }
.loyalty-buttons { display: flex; gap: 12px; justify-content: center; }

/* ===== Popular Links Tabs ===== */
.popular-tabs {
  display: flex; flex-wrap: wrap; gap: 8px;
  margin-bottom: 28px; justify-content: center;
}
.popular-tab {
  padding: 10px 22px;
  border-radius: 24px;
  font-size: 0.9rem; font-weight: 500;
  color: var(--gray-600);
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  transition: all 0.15s; cursor: pointer;
  font-family: inherit;
}
.popular-tab:hover { border-color: var(--blue); color: var(--blue); }
.popular-tab.active { background: var(--navy); color: var(--white); border-color: var(--navy); }
.popular-links-list {
  display: flex; flex-wrap: wrap; gap: 12px;
  justify-content: center;
}
.popular-link-item {
  padding: 8px 16px;
  color: var(--gray-600); font-size: 0.9rem;
  transition: color 0.15s; cursor: pointer;
  text-decoration: none;
}
.popular-link-item:hover { color: var(--blue); text-decoration: underline; }

/* ===== Benefits Section ===== */
.benefits-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
.benefit-card {
  text-align: center; padding: 36px 24px;
  border-radius: var(--radius-lg);
  background: var(--white);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-200);
}
.benefit-icon {
  width: 56px; height: 56px; border-radius: 50%;
  background: var(--blue-light); margin: 0 auto 16px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem;
}
.benefit-card h3 { margin-bottom: 8px; }
.benefit-card p { color: var(--gray-500); font-size: 0.925rem; }

/* ===== Companies Grid (Car Rental) ===== */
.companies-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 20px; }
.company-card {
  display: flex; align-items: center; justify-content: center;
  padding: 28px 20px; border-radius: var(--radius);
  background: var(--white); border: 1px solid var(--gray-200);
  font-size: 1.1rem; font-weight: 700; color: var(--gray-700);
  transition: all 0.15s; cursor: pointer;
  letter-spacing: -0.01em;
}
.company-card:hover { box-shadow: var(--shadow); border-color: var(--gray-300); }

/* ===== FAQ Accordion ===== */
.faq-list { max-width: 780px; margin: 0 auto; }
.faq-item { border-bottom: 1px solid var(--gray-200); }
.faq-question {
  width: 100%; padding: 20px 0;
  display: flex; align-items: center; justify-content: space-between;
  font-size: 1rem; font-weight: 600;
  color: var(--gray-800); text-align: left;
  transition: color 0.15s; cursor: pointer;
  font-family: inherit;
}
.faq-question:hover { color: var(--blue); }
.faq-question::after {
  content: '+'; font-size: 1.4rem; font-weight: 300;
  color: var(--gray-400); transition: transform 0.2s;
  margin-left: 16px; flex-shrink: 0;
}
.faq-item.open .faq-question::after { content: '−'; transform: rotate(180deg); }
.faq-answer {
  max-height: 0; overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}
.faq-item.open .faq-answer { max-height: 200px; padding-bottom: 20px; }
.faq-answer p { color: var(--gray-600); font-size: 0.925rem; line-height: 1.65; }

/* ===== Destination Tabs (Car Rental) ===== */
.dest-tabs {
  display: flex; flex-wrap: wrap; gap: 8px;
  margin-bottom: 28px; justify-content: center;
}
.dest-tab {
  padding: 10px 22px;
  border-radius: 24px;
  font-size: 0.9rem; font-weight: 500;
  color: var(--gray-600);
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  transition: all 0.15s; cursor: pointer;
  font-family: inherit;
}
.dest-tab:hover { border-color: var(--blue); color: var(--blue); }
.dest-tab.active { background: var(--navy); color: var(--white); border-color: var(--navy); }

/* Rental destination rows */
.rental-dest-table { width: 100%; max-width: 900px; margin: 0 auto; }
.rental-dest-row {
  display: grid; grid-template-columns: 1fr auto auto;
  align-items: center; gap: 24px;
  padding: 16px 0; border-bottom: 1px solid var(--gray-100);
  cursor: pointer; transition: background 0.15s;
}
.rental-dest-row:hover { background: var(--gray-50); margin: 0 -16px; padding: 16px; border-radius: var(--radius); }
.rental-dest-row h4 { font-size: 0.95rem; margin-bottom: 2px; }
.rental-dest-row .loc-count { font-size: 0.8rem; color: var(--gray-500); }
.rental-dest-row .price { font-weight: 700; color: var(--gray-800); }
.rental-dest-row .price-period { font-size: 0.8rem; color: var(--gray-500); }

/* ===== Attraction Cards ===== */
.attr-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.attr-card {
  border-radius: var(--radius-lg); overflow: hidden;
  background: var(--white);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-200);
  transition: all 0.2s; cursor: pointer;
}
.attr-card:hover { box-shadow: var(--shadow); transform: translateY(-2px); }
.attr-card-img {
  height: 180px;
  background: linear-gradient(135deg, #dbeafe, #c7d2fe);
  display: flex; align-items: center; justify-content: center;
}
.attr-card-img .placeholder-icon { font-size: 2.5rem; opacity: 0.4; }
.attr-card-body { padding: 16px; }
.attr-card-body h3 { font-size: 0.925rem; margin-bottom: 4px; font-weight: 600; line-height: 1.3; }
.attr-card-body .attr-meta { font-size: 0.8rem; color: var(--gray-500); }

/* Nearby destinations */
.nearby-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.nearby-card {
  position: relative; border-radius: var(--radius-lg); overflow: hidden;
  aspect-ratio: 3/2; cursor: pointer;
  background: linear-gradient(135deg, #c7d2fe, #a5b4fc);
  display: flex; align-items: flex-end; transition: transform 0.2s;
}
.nearby-card:hover { transform: translateY(-2px); }
.nearby-overlay {
  padding: 20px; width: 100%;
  background: linear-gradient(transparent, rgba(0,0,0,0.7));
  color: var(--white);
}
.nearby-overlay h3 { color: var(--white); font-size: 1rem; margin-bottom: 2px; }
.nearby-overlay span { font-size: 0.8rem; opacity: 0.85; }

/* ===== Attractions CTA ===== */
.account-cta {
  background: var(--gray-50); padding: 64px 0;
  text-align: center;
}
.account-cta h2 { margin-bottom: 4px; }
.account-cta .subtitle { color: var(--gray-500); margin-bottom: 8px; }
.account-cta p { color: var(--gray-600); margin-bottom: 20px; max-width: 500px; margin-left: auto; margin-right: auto; }

/* ===== Things to Do Tabs ===== */
.things-tabs {
  display: flex; flex-wrap: wrap; gap: 8px;
  margin-bottom: 28px; justify-content: center;
}
.things-tab {
  padding: 10px 20px;
  border-radius: 24px;
  font-size: 0.9rem; font-weight: 500;
  color: var(--gray-600);
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  transition: all 0.15s; cursor: pointer;
  font-family: inherit;
}
.things-tab:hover { border-color: var(--blue); color: var(--blue); }
.things-tab.active { background: var(--navy); color: var(--white); border-color: var(--navy); }
.things-links { display: flex; flex-wrap: wrap; gap: 12px; justify-content: center; }
.things-link-item {
  padding: 8px 16px;
  color: var(--gray-600); font-size: 0.9rem;
  transition: color 0.15s; cursor: pointer;
  text-decoration: none;
}
.things-link-item:hover { color: var(--blue); text-decoration: underline; }

/* ===== Credit Card Promo ===== */
.cc-promo {
  background: linear-gradient(135deg, #fef9e7, #fff3cd);
  padding: 48px 0; text-align: center;
}
.cc-promo h3 { font-size: 1.3rem; margin-bottom: 8px; }
.cc-promo p { color: var(--gray-600); margin-bottom: 16px; max-width: 500px; margin-left: auto; margin-right: auto; }

/* ===== Explore destinations with region tabs ===== */
.region-tabs {
  display: flex; flex-wrap: wrap; gap: 8px;
  margin-bottom: 28px; justify-content: center;
}
.region-tab {
  padding: 10px 20px;
  border-radius: 24px;
  font-size: 0.9rem; font-weight: 500;
  color: var(--gray-600);
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  transition: all 0.15s; cursor: pointer;
  font-family: inherit;
}
.region-tab:hover { border-color: var(--blue); color: var(--blue); }
.region-tab.active { background: var(--navy); color: var(--white); border-color: var(--navy); }
.explore-dest-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; }
.explore-dest-item {
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 18px;
  border-radius: var(--radius);
  background: var(--white);
  border: 1px solid var(--gray-200);
  transition: all 0.15s; cursor: pointer;
}
.explore-dest-item:hover { box-shadow: var(--shadow-sm); border-color: var(--gray-300); }
.explore-dest-item h4 { font-size: 0.925rem; font-weight: 600; }
.explore-dest-item span { font-size: 0.8rem; color: var(--gray-500); }

/* ===== Footer ===== */
.site-footer {
  background: var(--gray-900);
  color: var(--gray-400);
  padding: 64px 0 0;
}
.footer-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 40px; padding-bottom: 48px; }
.footer-col h4 { color: var(--white); font-size: 0.9rem; margin-bottom: 16px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.03em; }
.footer-col a {
  display: block; color: var(--gray-400); font-size: 0.875rem;
  padding: 4px 0; transition: color 0.15s; text-decoration: none;
}
.footer-col a:hover { color: var(--white); text-decoration: underline; }
.footer-bottom {
  border-top: 1px solid var(--gray-700);
  padding: 24px 0;
  text-align: center;
  font-size: 0.8rem;
  color: var(--gray-500);
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .trust-grid { grid-template-columns: repeat(2, 1fr); }
  .destinations-grid { grid-template-columns: repeat(3, 1fr); }
  .homes-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: repeat(2, 1fr); }
  .companies-grid { grid-template-columns: repeat(3, 1fr); }
  .explore-dest-grid { grid-template-columns: repeat(3, 1fr); }
  .trip-destinations { grid-template-columns: repeat(2, 1fr); }
  .carousel-btn--prev { left: 8px; }
  .carousel-btn--next { right: 8px; }
}

@media (max-width: 768px) {
  h1 { font-size: 1.75rem; }
  h2 { font-size: 1.35rem; }
  .section { padding: 48px 0; }
  .hero { padding: 56px 0 40px; }
  .hero h1 { font-size: 1.75rem; }
  .search-card { flex-direction: column; padding: 12px; }
  .search-field::after { display: none; }
  .search-field { width: 100%; padding: 8px 12px; border-bottom: 1px solid var(--gray-100); }
  .search-btn { width: calc(100% - 8px); }
  .trust-grid { grid-template-columns: 1fr; gap: 20px; }
  .offers-grid { grid-template-columns: 1fr; }
  .destinations-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .homes-grid { grid-template-columns: 1fr; }
  .companies-grid { grid-template-columns: repeat(2, 1fr); }
  .benefits-grid { grid-template-columns: 1fr; }
  .explore-dest-grid { grid-template-columns: repeat(2, 1fr); }
  .nearby-grid { grid-template-columns: repeat(2, 1fr); }
  .attr-cards { grid-template-columns: 1fr; }
  .trip-destinations { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 28px; }
  .carousel-btn { display: none; }
  .nav-links { display: none; }
  .nav-links.open {
    display: flex; flex-direction: column;
    position: absolute; top: var(--header-height); left: 0; right: 0;
    background: var(--navy-dark); padding: 16px;
    gap: 4px;
  }
  .mobile-menu-btn { display: block; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .destinations-grid { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .rental-dest-row { grid-template-columns: 1fr; gap: 4px; }
  .package-radios { flex-direction: column; }
}
